import {validateMessage} from './validation.js';

// One wire name for the client frame: the alias is gone, and the frame the validator returns is the exported shape.

describe('the websocket frame validator', () => {
  it('accepts user_message and returns the frame the exported union describes', () => {
    const result = validateMessage({type: 'user_message', content: 'hello'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  it('rejects send_message, which is no longer a wire name', () => {
    const result = validateMessage({type: 'send_message', content: 'hello'});

    expect(result).toEqual({valid: false, error: 'Unknown message type: send_message'});
  });

  it('drops any field the frame does not define, rather than forwarding it', () => {
    const result = validateMessage({type: 'user_message', content: 'hello', chatId: 'c1'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  it('accepts a bare list_sessions and forwards only limit and a well-formed before cursor', () => {
    const bare = validateMessage({type: 'list_sessions'});
    const paged = validateMessage({
      type: 'list_sessions',
      limit: 10,
      before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's1', extra: 1},
      userId: 'u2',
    });

    expect({bare, paged}).toEqual({
      bare: {valid: true, data: {type: 'list_sessions'}},
      paged: {
        valid: true,
        data: {type: 'list_sessions', limit: 10, before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's1'}},
      },
    });
  });

  it('rejects a list_sessions with a malformed limit or before cursor', () => {
    const cursor = {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's1'};
    const bad = [
      {limit: 'ten'},
      {limit: -1},
      {limit: 1.5},
      {before: 'not-an-object'},
      {before: {...cursor, sessionId: ''}},
      {before: {...cursor, sessionId: 'a'.repeat(129)}},
      {before: {...cursor, updatedAt: 'not-a-date'}},
      {before: {...cursor, updatedAt: true}},
    ];

    const results = bad.map(fields => validateMessage({type: 'list_sessions', ...fields}).valid);

    expect(results).toEqual(bad.map(() => false));
  });
});
