export async function closeAll(
  clients: WebSocket[],
  servers: Array<Pick<HalServer, 'wss' | 'stop'>>
): Promise<void> {
  clients.splice(0).forEach(client => client.terminate());
  await Promise.all(
    servers.splice(0).map(async hal => {
      await eventually(() => hal.wss.clients.size === 0);
      return hal.stop();
    })
  );
}

